// A shared stage: preserve readable controls, then give unused space to the actual game visual.
let boardFitFrame=0;
function fitSmartboard(){cancelAnimationFrame(boardFitFrame);const p=$('#player');p.classList.remove('board-dense');if(!game||ui.view!=='player')return;p.style.setProperty('--team-count',game.session?.groups?.length||4);p.dataset.presentation=(ACTIVITIES[game.lesson.format]||['match','territory'].includes(game.lesson.format))?'board':'scene';p.classList.toggle('stage-finished',!!game.done);const layoutKey=innerWidth+':'+innerHeight+':'+(game.session?.lanes?.map(l=>l.index).join('-')??game.index)+':'+game.done;if(p.dataset.presentation==='board'&&p.boardOwner===game&&p.boardKey===layoutKey)return;p.boardOwner=game;p.boardKey=layoutKey;p.style.setProperty('--visual-bonus','0px');
boardFitFrame=requestAnimationFrame(()=>{boardFitFrame=0;if(ui.view!=='player')return;const a=$('#arena');if(innerWidth<1024)return;if(p.dataset.presentation==='scene'&&!game.done){const css=getComputedStyle(a),kids=[...a.children].filter(c=>getComputedStyle(c).position!=='absolute'),top=a.getBoundingClientRect().top;const content=Math.max(0,...kids.map(c=>c.getBoundingClientRect().bottom-top))+parseFloat(css.paddingBottom);const canvas=$('#game-canvas'),visible=[...p.children].filter(c=>c!==a&&c!==canvas&&getComputedStyle(c).display!=='none'),available=p.clientHeight-visible.reduce((sum,c)=>sum+c.getBoundingClientRect().height,0)-40,controls=content;const scene=Math.max(130,available-Math.max(180,controls)-12);p.style.setProperty('--scene-height',Math.floor(scene)+'px');}else if(p.dataset.presentation==='board'){const panels=[...a.querySelectorAll('.geo-panel')];const roots=panels.length?panels:[a];const used=Math.max(0,...roots.map(r=>{const rr=r.getBoundingClientRect();return Math.max(0,...[...r.children].map(c=>c.getBoundingClientRect().bottom-rr.top));}));const available=panels.length?a.clientHeight-(a.querySelector('.geo-team-tabs')?.getBoundingClientRect().height||0)-32:a.clientHeight;const bonus=Math.max(0,Math.min(220,available-used-28));p.style.setProperty('--visual-bonus',Math.floor(bonus)+'px');}});}
const boardRender=renderGame;renderGame=function(){boardRender();fitSmartboard();};
window.addEventListener('resize',fitSmartboard);document.addEventListener('fullscreenchange',fitSmartboard);
const homeButton=document.createElement('button');homeButton.id='game-home';homeButton.className='text-button';homeButton.textContent='⌂ Main screen';homeButton.onclick=()=>leaveEditor(async()=>{if(document.fullscreenElement)await document.exitFullscreen().catch(()=>{});ui.collection='library';show('home');renderLibrary();$('#library-title').focus({preventScroll:true});});$('.play-toolbar').prepend(homeButton);
// Independent game engines update their boards without going through renderGame.
new MutationObserver(changes=>{if(game&&ui.view==='player'&&!boardFitFrame&&changes.some(m=>m.target===document.querySelector('#arena')||m.target.matches?.('.geo-panel,.tug-side,.lab-game')))fitSmartboard();}).observe($('#arena'),{childList:true,subtree:true});
fitSmartboard();
